import Foundation
protocol ConsentSource {
    func request(_ reply: @escaping (Bool) -> Void)
}
struct LocalConsentSource: ConsentSource {
    func request(_ reply: @escaping (Bool) -> Void) {
        reply(true)
        reply(false)
    }
}
final class ConsentReply {
    private let lock = NSLock()
    private var pending: CheckedContinuation<Bool, Never>?
    init(_ continuation: CheckedContinuation<Bool, Never>) {
        pending = continuation
    }
    func resolve(_ accepted: Bool) {
        lock.lock()
        let continuation = pending
        pending = nil
        lock.unlock()
        continuation?.resume(returning: accepted)
    }
}
func requestConsent(source: any ConsentSource) async -> Bool {
    await withCheckedContinuation { continuation in
        let reply = ConsentReply(continuation)
        source.request { reply.resolve($0) }
    }
}

Локальный источник true/false даст true. ConsentReply забирает continuation под блокировкой и обнуляет до resume; второй вызов не возобновляет её повторно. Если источник никогда не ответит, адаптер зависнет: это отдельное нарушение контракта.
